 */
export declare class TimeValue implements CommandValue {
    private readonly amount;
    private readonly unit;
    constructor(amount: number, unit: Unit);
    render(): string;
}
export type Time = TimeValue;
export declare const Time: ((ticks: number) => TimeValue) & {
    ticks: (n: number) => TimeValue;
    seconds: (n: number) => TimeValue;
    days: (n: number) => TimeValue;
};
export {};

