/** A 3-component vector (translation / scale / offset). */
export type Vec3 = [number, number, number];
/** A quaternion `[x, y, z, w]` (Minecraft's left/right rotation form). */
export type Quat = [number, number, number, number];
export type Axis = "x" | "y" | "z";
/** Round to 6 dp for stable, readable output, normalising `-0` to `0`. */
export declare function round6(n: number): number;
/** Linear interpolate two numbers: `a` at `u=0`, `b` at `u=1`. */
export declare function lerp(a: number, b: number, u: number): number;
/** Component-wise linear interpolate two 3-vectors. */
export declare function lerpVec3(a: Vec3, b: Vec3, u: number): Vec3;
export declare function add(a: Vec3, b: Vec3): Vec3;
export declare function sub(a: Vec3, b: Vec3): Vec3;
/** Axis-angle (degrees) to a unit quaternion `[x, y, z, w]`. */
export declare function quat(axis: Axis, angleDeg: number): Quat;
/** Rotate a vector by a quaternion: `v' = v + 2w(u×v) + 2u×(u×v)`, `u = q.xyz`. */
export declare function rotateVec(v: Vec3, q: Quat): Vec3;
/** World position of a member at local `offset` after rotating about `pivot`. */
export declare function rotateAboutPivot(offset: Vec3, pivot: Vec3, q: Quat): Vec3;

